theme.css:
/* theme: Half-Recovered Ledger | Wall Street clawed back almost everything while peace stayed out of reach — the page inks that ledger line in amber and grey. */
/* mood: tense */
/* layout: hero=poster; major-events=banner/grid-2; political-news=timeline/stack; financial-news=stat/grid-2; tech-news=outline/grid-3; entertainment-news=numbered/grid-2; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/stack */

.diary-page {
  --paper: #1d1607;
  --paper-alt: #2a2110;
  --ink: #f9eccf;
  --ink-soft: #e5d5a8;
  --muted: #a8986f;
  --accent: #ffad33;
  --accent-ink: #1a1204;
  --rule: #4a3f22;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background: var(--accent);
  border-bottom: 3px solid var(--accent);
}

.diary-page[data-hero="poster"] .diary-hero-inner {
  padding-block: 3rem 4rem;
}

.diary-page[data-hero="poster"] .diary-title {
  font-size: clamp(3.5rem, 12vw, 8rem);
  letter-spacing: 0.04em;
  line-height: 0.9;
  text-transform: uppercase;
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-summary {
  max-width: 34rem;
  font-family: var(--font-ui);
  font-size: 0.95rem;
  letter-spacing: 0.12em;
  line-height: 1.7;
  text-transform: uppercase;
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-theme-note {
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-style: italic;
  letter-spacing: 0;
  text-transform: none;
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-theme-name {
  background: var(--accent-ink);
  color: var(--accent);
  border-radius: 0;
  padding: 0.15rem 0.4rem;
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  font-weight: 700;
  letter-spacing: 0.3em;
  color: var(--accent);
}

.diary-page[data-hero="poster"] .diary-kicker {
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-crumbs a {
  color: var(--accent-ink);
}

.diary-page .diary-crumbs a::before {
  content: "← ";
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-toc {
  background: #151006;
  border-bottom-color: var(--rule);
}

.diary-page .diary-toc-label {
  color: var(--accent);
}

.diary-page .diary-toc-link {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  color: var(--muted);
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
}

.diary-page .diary-toc-number {
  font-family: var(--ff-syne), sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--accent);
}

.diary-page .diary-section { border-top-color: var(--rule); }

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-prose {
  font-size: 1.1rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose h3 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.25em;
  color: var(--ink);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong { color: var(--ink); }

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before { background: var(--accent); }

.diary-page .diary-prose code, .diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-footer a { color: var(--ink); }
.diary-page .diary-footer a:hover { color: var(--accent); }

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.6rem;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--ink);
  line-height: 1.05;
}

.diary-page .diary-card-body { font-size: 1.08rem; }

.diary-page .diary-card--banner .diary-card-inner {
  border: 2px solid var(--accent);
  background: var(--paper);
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.25rem;
  padding: 1rem 1.25rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--accent);
  width: 1px;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--paper-alt);
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 0.75rem;
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 14cqi, 4rem);
  color: var(--accent);
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 2px solid var(--accent);
  border-radius: 0;
  padding: 1.25rem;
  background: var(--paper);
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.5rem;
  color: var(--accent);
}

.diary-page .diary-card--split .diary-card-inner {
  border-top: 3px solid var(--accent);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--paper-alt);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card-lede {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-markets {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-spark.is-up { color: var(--accent); }

.diary-page .diary-spark.is-down { color: #ff6b6b; }

.diary-page .diary-spark .diary-spark-value { color: var(--ink); }

.diary-page .diary-spark .diary-spark-change { color: var(--accent); }

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page *,
  .diary-page *::before,
  .diary-page *::after {
    animation: none !important;
    transition: none !important;
  }
}
